mappings.INQUIRY.response:
status = 200 and body.status = "DUE" and $type(body.amount) = "string"
  ? {"outcome": "SUCCESS", "partnerRef": body.billNo,
     "attributes": {"amount": body.amount, "dueDate": body.dueDate, "billPeriod": body.billMonth}}
: status = 200 and body.status = "SUCCESS"
  ? {"outcome": "FAILED", "code": "402", "message": "Bill already paid"}
: (status = 422 or status = 404) and $type(body.respCode) = "string" and body.respCode != ""
  ? {"outcome": "FAILED", "code": body.respCode, "message": body.respMsg}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.PAY.response:
status = 200 or status = 202
  ? (body.status = "SUCCESS" and $type(body.trxId) = "string" and body.trxId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.trxId}
    : body.status = "PROCESSING"
      ? {"outcome": "PENDING", "partnerRef": body.trxId}
    : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 422 or status = 404) and $type(body.respCode) = "string" and body.respCode != ""
  ? {"outcome": "FAILED", "code": body.respCode, "message": body.respMsg}
: status = 400
  ? {"outcome": "FAILED", "code": "HTTP_400"}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.status = "SUCCESS" and $type(body.trxId) = "string" and body.trxId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.trxId}
    : body.status = "PROCESSING"
      ? {"outcome": "PENDING", "partnerRef": body.trxId}
    : body.status = "FAILED" and $type(body.respCode) = "string"
      ? {"outcome": "FAILED", "code": body.respCode, "message": body.respMsg}
    : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.respCode}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 200
  ? (body.status = "REVERSED" and $type(body.reversalTrxId) = "string" and body.reversalTrxId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.reversalTrxId}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 422 or status = 404) and $type(body.respCode) = "string" and body.respCode != ""
  ? {"outcome": "FAILED", "code": body.respCode, "message": body.respMsg}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.CALLBACK.response:
$type(body.requestId) != "string" or body.requestId = "" ? {}
: body.status = "SUCCESS" and $type(body.trxId) = "string" and body.trxId != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.trxId, "reference": body.requestId}
: body.status = "FAILED" and $type(body.respCode) = "string" and body.respCode != ""
  ? {"outcome": "FAILED", "partnerRef": body.trxId, "reference": body.requestId,
     "code": body.respCode, "message": body.respMsg}
: {}
